const ScreenVisitReplayModal = ({
  data,
  rowsData,
  currentPage,
  setCurrentPage,
  showScreenModal,
  setShowScreenModal,
  currentVisitIndex,
  setCurrentVisitIndex,
  setUserPausedVideo,
  playRequest,
  setIsPlayButton
}) => {

  const dispatch = useDispatch();
  const { screenNameUrlSuffix, replacedScreenName } = useScreenNameUrlSuffix()

  const { videoElemRef, prevSessionCallbackRef, nextSessionCallbackRef } = useSessionVideoControlls();

  const { setScreenNumber } = useSessionSidebar()

  const moveToRef = useRef();

  const multiScreenSkippedData = useScreenSkippedData();

  const {
    appFilter: {
      heatmap: { segment: filters },
      dateSegment
    },
    urlReducer: { appId, screenname, sessionid, screenVisitId },
  } = useSelector(({ appFilter, urlReducer }) => ({
    appFilter,
    urlReducer
  }));

  const isFirstScreen = useMemo(
    () => currentPage === 1 && currentVisitIndex < 1,
    [currentPage, currentVisitIndex]
  );
  const isLastScreen = useMemo(
    () =>
      data?.body?.length === currentVisitIndex + 1 &&
      data?.pagination?.next === null,
    [data, currentVisitIndex]
  );

  const session = useMemo(
    () =>
      data?.body
        ?.filter((el) => {
          if (el.sessionid === sessionid) {
            return el.userProperty;
          }
          return null;
        })
        .filter((el) => el)[0],
    [data, sessionid]
  );

  const handleModalClose = () => {
    dispatch(trackPageViews(null, {
      eventName: 'close_session_replay',
      track_type: 'event',
    }))
    setUserPausedVideo(false);
    setShowScreenModal(false);

    const screenUpdated = encodeSpecialCharsInScreenName(replacedScreenName);

    const query = `appId=${appId}&parentType=heatmapsList&screenname=${screenUpdated}&selectedTab=screenvisits`;
    let url = `/app/${appId}/screens/details/${screenUpdated}/screenvisits`;
    url = urlSegmentEncoder(url, filters);
    url = `${url}${screenNameUrlSuffix}`;

    Router.push(`/integration?${query}`, url);
  };

  const screenInfo = useMemo(
    () =>
      rowsData
        ?.filter((row, index) => {
          if (index === currentVisitIndex) {
            return row;
          }
          return null;
        })
        .filter((el) => el)[0],
    [rowsData, currentVisitIndex]
  );

  const onSelectedActiveRow = useCallback(
    (selectedSessionId, entryTime, visitIndex, screenNumber, id) => {
      const segmentDateFilter = [...filters, ...[{ ...dateSegment }]];
      if (videoElemRef?.current) {
        videoElemRef.current.currentTime = Number(entryTime);
        videoElemRef.current.pause();
      }
      // if (sessionid === selectedSessionId && videoElemRef?.current) videoElemRef.current.play(); removed for now -> to be discussed
      setScreenNumber(screenNumber - 1);
      setCurrentVisitIndex(Number(visitIndex));

      const screenUpdated = encodeSpecialCharsInScreenName(replacedScreenName);
      const query = `appId=${appId}&parentType=heatmapsList&screenname=${screenUpdated}&selectedTab=screenvisits&screenVisitPage=${currentPage}&screenVisitId=${id}&sessionid=${selectedSessionId}&starttime=${entryTime}&index=${visitIndex}`;
      let url = `/app/${appId}/screens/details/${screenUpdated}/screenvisits/${currentPage}/${id}/session/${selectedSessionId}/${entryTime}`;
      url = urlSegmentEncoder(url, segmentDateFilter);
      url = `${url}${screenNameUrlSuffix}`;

      Router.push(`/integration?${query}`, url);
    },
    [filters, dateSegment, videoElemRef, setScreenNumber, setCurrentVisitIndex, appId, currentPage, replacedScreenName, screenNameUrlSuffix]
  );

  const handlePrevScreenVisit = useCallback(() => {
    setUserPausedVideo(false); // to reset the overlay status when switching between the screens of same session
    moveToRef.current = undefined;

    if (!data || isFirstScreen) return;

    const prevIndex = currentVisitIndex - 1;
    const prevPage = prevIndex === -1;

    if (prevPage) {
      moveToRef.current = 'last';
      setCurrentVisitIndex(20);
      setCurrentPage(currentPage - 1);
    } else {
      const { sessionid: selectedSessionId, entryTime, screenNumber, id } = data.body[prevIndex];
      onSelectedActiveRow(selectedSessionId, entryTime, prevIndex, screenNumber, id);
    }
  }, [
    setUserPausedVideo,
    data,
    isFirstScreen,
    currentVisitIndex,
    setCurrentVisitIndex,
    setCurrentPage,
    currentPage,
    onSelectedActiveRow,
  ]);

  const handleNextScreenVisit = useCallback(() => {
    setUserPausedVideo(false); // to reset the overlay status when switching between the screens of same session

    moveToRef.current = undefined;

    if (!data || isLastScreen) return;

    const nextIndex = currentVisitIndex + 1;
    const isLastIndex = data?.body?.length === nextIndex;

    if (isLastIndex) {
      moveToRef.current = 'first';
      setCurrentVisitIndex(0);
      setCurrentPage(currentPage + 1);
    } else {
      const { sessionid: selectedSessionId, entryTime, screenNumber, id } = data.body[nextIndex];
      onSelectedActiveRow(selectedSessionId, entryTime, nextIndex, screenNumber, id);
    }
  }, [setUserPausedVideo, data, isLastScreen, currentVisitIndex, setCurrentVisitIndex, setCurrentPage, currentPage, onSelectedActiveRow]);

  useEffect(() => {
    nextSessionCallbackRef.current = handleNextScreenVisit;
  }, [handleNextScreenVisit, nextSessionCallbackRef]);

  useEffect(() => {
    prevSessionCallbackRef.current = handlePrevScreenVisit;
  }, [handlePrevScreenVisit, prevSessionCallbackRef]);

  useEffect(() => {
    if (sessionid) {
      setShowScreenModal(true);
      if (data?.body) {
        const screenVisitIndex = data.body.findIndex(({ id }) => id === screenVisitId);
        if (screenVisitIndex > -1) {
          const { screenNumber } = data.body[screenVisitIndex];
          setCurrentVisitIndex(screenVisitIndex);
          setScreenNumber(screenNumber - 1)
        }
      }
    }
  }, [data]);

  useEffect(() => {
    if(videoElemRef.current && playRequest) videoElemRef.current.play().catch( () => null );
    return () => {
      videoElemRef.current = null;
      setIsPlayButton(false)
    };
  }, [playRequest, setIsPlayButton, videoElemRef]);

  return (
    <ModalWrapper
      centered
      closable={false}
      footer={null}
      visible={showScreenModal}
      maskClosable={false}
      width={1100}
      wrapClassName='screens-replay-modal' 
    >
      <>
        {!isFirstScreen &&
          <ScreenTootltipTitle title='Previous visit' placement="left">
            <LeftActionButton
              icon={<LeftOutlined />}
              onClick={() => handlePrevScreenVisit()}
            />
          </ScreenTootltipTitle>}
        <HeaderActions>
          <HeaderTitle screenInfo={screenInfo} />
          <ShareSessionModalWrap><ShareSessionModal /></ShareSessionModalWrap>
          <Popover overlayClassName='custom-popover' content='Close'>
          <ButtonRound
            onClick={() => handleModalClose()}
          >
            <img src="/static/sessions/close.svg" alt="" />
          </ButtonRound>
          </Popover>
        </HeaderActions>
        <ScreenReplayWrapper>
          <ScreenReplaySection>
            <ScreenReplay
              sessionList={data}
              appId={appId}
              sessionId={sessionid}
              uploadedOn={session?.sessionUploadedDateTime}
              multiScreenSkippedData={multiScreenSkippedData}
            />
          </ScreenReplaySection>
          <ScreeenReplaySidebar>
            <SessionDetailSideBarV2
              multiScreenSkippedData={multiScreenSkippedData}
              uploadedOn={session?.sessionUploadedDateTime}
            />
          </ScreeenReplaySidebar>
        </ScreenReplayWrapper>

        {!isLastScreen &&
          <ScreenTootltipTitle title='Next visit' placement="right">
            <RightActionButton
              icon={<RightOutlined />}
              onClick={() => handleNextScreenVisit()}
            />
          </ScreenTootltipTitle>
        }
      </>
    </ModalWrapper>
  );
};

const ScreenVisitPage = memo(() => {

  const dispatch = useDispatch();

  const { setUserPausedVideo } = useSessionVideoContext();

  const [cachedHeaders, setCachedHeaders] = useLocalStorage('screenVisitHeaders', defaultHeaders);
  const [cachedSortBy, setSortBy] = useLocalStorage('screenVisitSortBy', '');

  const tableHeaders = isEqual(defaultHeaders, cachedHeaders) ? cachedHeaders : defaultHeaders;

  const sortOrder = useMemo(
    () =>
      cachedSortBy || [{ sortName: 'screen_uploadedon', sortOrder: 'desc' }],
    [cachedSortBy]
  );
  const [headers] = useState(tableHeaders);
  const [sortedState, setSortedState] = useState();

  const [currentVisitIndex, setCurrentVisitIndex] = useState();
  const [showScreenModal, setShowScreenModal] = useState(false);
  const [playRequest, setIsPlayButton] = useState(false)

  const { setScreenNumber } = useSessionSidebar()

  const {
    appFilter: {
      heatmap: { segment: filters },
      dateSegment
    },
    urlReducer: { appId, screenname, sessionid, screenVisitPage = 1 },
    commonReducer: {bottomBarClassFlag},
    currentOrgReducer: { planLimit }
  } = useSelector(({ appFilter, urlReducer, commonReducer, currentOrgReducer }) => ({
    appFilter,
    urlReducer,
    commonReducer,
    currentOrgReducer,
  }));
  const [currentPage, setCurrentPage] = useState(Number(screenVisitPage));
  const [filterState, setFilterState]= useState(filters)
  const reqBody = useMemo(
    () => {
      let sortOrderValue = 'desc';
      if (sortedState) {
        sortOrderValue = sortedState[0]?.desc ? 'desc' : 'asc';
      }
      return {
        appid: appId,
        screen_name: screenname,
        date_range: dateSegment,
        mega_filters: formattedFilters(filterState) || [],
        orderBy: [{
          sortName: screenVisitAttribute[sortedState?.[0]?.id] || 'screen_uploadedon',
          sortOrder: sortOrderValue,
        }] || sortOrder,
        page: currentPage,
      };
    },
    [appId, screenname, dateSegment, filterState, sortedState, sortOrder, currentPage]
  );

  const { replacedScreenName } = useScreenNameUrlSuffix()
  const { data, isLoading, isFetching } = useScreenVisitList(reqBody);
  const {pagination, setPagination} = usePagination();
  // const { pagination } = data || {};
  const { monthsOfVideosAccessible } = useRestrictionContext();

  const fetchScreenVisit = useCallback(
    (sortBy) => {
      const { id: name, desc: isDescending } = sortBy()[0];
      const sortName = screenVisitAttribute[name];
      const orderBy = [{ sortName, sortOrder: isDescending ? 'desc' : 'asc' }];
      setSortBy(orderBy);
      setSortedState(sortBy);
    },
    [setSortBy]
  );

  const trackEvent = useCallback(() => {
    screenname && dispatch(trackPageViews(null, {
      eventName: 'hm_open_screen_replay',
      track_type: 'event',
      eventProperty: {
        screenname
      },
    }))
  }, [dispatch, screenname])

  const onSelectScreenVisitRow = useCallback(
    (row, e) => {
      const { sessionid: selectedSessionId, entryTime, screenNumber, id } = row;
      const autoPlayPart = typeof(e) === 'string' ? '#autoplay' : '';
      const segmentDateFilter = [...filterState, ...[{ ...dateSegment }]];
      trackEvent();

      setShowScreenModal(true);
      setScreenNumber(screenNumber - 1);
      setCurrentVisitIndex(Number(e));
      setIsPlayButton(typeof(e) === 'string')

      const screenUpdated = encodeSpecialCharsInScreenName(replacedScreenName);

      const query = `appId=${appId}&parentType=heatmapsList&screenname=${screenUpdated}&selectedTab=screenvisits&screenVisitPage=${currentPage}&screenVisitId=${id}&sessionid=${selectedSessionId}&starttime=${entryTime}&index=${row?.id}${autoPlayPart}`;
      let url = `/app/${appId}/screens/details/${screenUpdated}/screenvisits/${currentPage}/${id}/session/${selectedSessionId}/${entryTime}`;
      const screenNameSuffix = `&screenname=${screenUpdated}`
      url = urlSegmentEncoder(url, segmentDateFilter);
      url = `${url}${screenNameSuffix}${autoPlayPart}`;
      Router.push(`/integration?${query}`, url);
    },
    [filterState, dateSegment, trackEvent, setScreenNumber, appId, currentPage, replacedScreenName]
  );

  const columns = useScreenVisitColumns(headers);

  const dataWithSessionLocked = useMemo(
    () => (
      {
        ...data,
        body: data?.body?.map((item) => ({
          ...item,
          sessionLocked: monthsOfVideosAccessible && isDateOlderThanMonths( item.sessionUploadedDateTime, monthsOfVideosAccessible ) && planLimit?.videoRetentionTime !== planLimit?.videoPlaybackAccessibleTime
        }))
      }
    ),
    [data, monthsOfVideosAccessible, planLimit]
  );

  const rowsData = useMemo(
    () =>
      dataWithSessionLocked?.body?.map((item) => ({
        ...item,
        onRowClick: onSelectScreenVisitRow,
      })),
    [dataWithSessionLocked, onSelectScreenVisitRow]
  );

  const handlePagination = useCallback((pageNo) => {
    setCurrentPage(pageNo)
  }, [setCurrentPage])

  useEffect(() => {
    setCachedHeaders(tableHeaders)
  }, [setCachedHeaders, tableHeaders]);

  useEffect(() => {
    currentPage > 1 &&
      dispatch(trackPageViews(null, {
        eventName: 'hm_navigate_screen_analytics_table',
        track_type: 'event',
        eventProperty: {
          'resulting page': currentPage,
          screenname
        }
      },
      ))
  }, [currentPage, dispatch, screenname]);

  useEffect(() => {
    sortedState && dispatch(
      trackPageViews(null, {
        eventName: 'hm_sort_screen_analytics_table',
        track_type: 'event',
        eventProperty: {
          columnHeader: sortedState[0]?.sortName,
          order: sortedState[0]?.sortOrder === 'desc' ? 'descending' : 'ascending',
          screenname
        },
      })
    );
  }, [sortedState, dispatch, screenname])

  useEffect(() => {
    try {
      localStorage.setItem('screensListReqBody', JSON.stringify(reqBody));
    } catch (err) {
      // silent fail
    }
  }, [reqBody])

  useEffect(()=>{
    setCurrentPage(1)
    setFilterState(filters)
  }, [filters])

  return (
    <>
      <SessionLockedModal />
      <TableWrap bottomBarClassFlag={bottomBarClassFlag}>
        <StylesProvider>
          <DashboardTable
            data={rowsData || []}
            columns={columns}
            sorting={sortedState}
            setSorting={fetchScreenVisit}
            resizeMode="onChange"
            isLoading={isLoading || isFetching}
            expandedView={false}
            pagination={{
              ...pagination,
              totalPagination: data?.pagination?.pages || 1,
            }}
            setPagination={setPagination}
            handleRouteUpdate={handlePagination}
            tableHeight='100%'
            tableWidth='100%'
            emptyText={{message: 'No screen visits match the current filters.'}}
          />
        </StylesProvider>
      </TableWrap>
      {sessionid && (
        <ScreenVisitReplayModal
          data={data}
          rowsData={rowsData}
          currentPage={currentPage}
          setCurrentPage={setCurrentPage}
          showScreenModal={showScreenModal}
          setShowScreenModal={setShowScreenModal}
          currentVisitIndex={currentVisitIndex}
          setCurrentVisitIndex={setCurrentVisitIndex}
          setUserPausedVideo={setUserPausedVideo}
          playRequest={playRequest}
          setIsPlayButton={setIsPlayButton}
        />
      )}
    </>
  );
});

export default ScreenVisitPage;
