import { useSelector } from 'react-redux';
import Link from 'next/link';
import { formatPlayerTime, getDate } from 'Utils/DateConversion/dateConversionUtils';
import CellOverflowTooltip from 'Utils/helpers/CellOverflowTooltip';
import { formatDisplayTime } from 'Utils/constants/index';
import { compactNotation, convertGetTime } from 'Utils/helpers/commonUtils';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import PauseIcon from 'public/static/session-replay/paused.svg';
import NoVideoIcon from 'public/static/session-replay/no-video.svg';
import PlayLockIcon from 'public/static/lock-features/player-lock-icon.svg';
import { createColumnHelper } from '@tanstack/react-table';
import { Tooltip } from 'antd';
import { getUserId } from 'Utils/helpers/userIdUtils';
import classNames from 'classnames';
import useRenamedScreenName from './useRenamedScreenName';
import { useScreenNameUrlSuffix } from './useScreenNameUrlSuffix';
import { screensParentType } from '../constants';


const Wrapper = styled.div`
`;

const ScreenNameStyled = styled.div`
  color: #090F19;
  line-height: 15px;
  text-decoration: underline;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
`;
const WrapperDate = styled.div``;
const StyledSpan = styled.div`
  font-size: 12px;
  color: #8a99b1;
  margin-top: 5px;
`;

const LocationWrap = styled.div`
  display: flex;
  flex-direction: column;
  margin: 5px;
`

const ButtonAndTime = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-right: 10px;
  width: 80px;

  button {
    margin: 0;
    padding: 0;
    cursor: pointer;
    background-color: transparent;
    border: none;
    padding: 7px;
    padding-top: 0px;
  }

  span {
    margin-top: 2px;
    opacity: 0.6;
    font-size: 12px !important;
    line-height: 0.8125rem;
    margin-top: -4px;
    pointer-events: none;
    color: #A2A5AE;
  }
`;

const HeaderSpan = styled.span`
  width: 100%;
`

const ScreenNameRow = memo(({ id, width, row }) => {
  const { _id: appId } = useSelector(state => state.currentAppReducer);
  const { dateSegment } = useSelector(state => state.appFilter);
  const { previousScreenName, nextScreenName } = row.original;
  const screenname = id === 'previousScreenName' ? previousScreenName : nextScreenName;
  const { screenNameUrlSuffix, replacedScreenName } = useScreenNameUrlSuffix({ screenname })
  const { tooltipElement, renamedScreenName } = useRenamedScreenName(screenname);
  const rowWidth = width - 30;
  const screenHref = useMemo(
    () => ({
      pathname: '/integration',
      query: {
        parentType: screensParentType,
        appId,
        screenname: encodeURIComponent(screenname),
        screenpage: 1,
      },
    }),
    [appId, screenname]
  );
  const url = useMemo(() => `/app/${appId}/screens/details/${encodeURIComponent(replacedScreenName)}`, [appId, replacedScreenName]);
  const asUrl = urlSegmentEncoder(url, [...[dateSegment]])
  return (
    <Wrapper onClick={(e) => e.stopPropagation()}>
      {screenname === 'Exit' || screenname === 'Launch' ?
        <span>{screenname}</span>
        :
        <Link
          passHref
          href={screenHref}
          as={`${asUrl}${screenNameUrlSuffix}`}
          legacyBehavior
        >
          <a href="#!" target="_blank" rel="noreferrer">
            <ScreenNameStyled>
              <CellOverflowTooltip
                width={rowWidth}
                text={screenname}
                value={renamedScreenName}
                tooltipElement={tooltipElement}
              />
            </ScreenNameStyled>
          </a>
        </Link>}
    </Wrapper>
  );
});

const UserName = memo(({ userIdentityName, uxcamuserid, hasCustomUserId }) => {
  const { appId } = useSelector(state => state.urlReducer);
  const { dateSegment } = useSelector(state => state.appFilter);
  const asUrl = urlSegmentEncoder(`/app/${appId}/users/list/1/${uxcamuserid}`, [...[dateSegment]])
  const getUserHref = useMemo(
    () => ({
      pathname: '/integration',
      query: {
        parentType: 'usersList',
        appId,
        sessionPage: 1,
        userpage: 1,
      },
    }),
    [appId]
  );
  return <Wrapper onClick={(e) => e.stopPropagation()}>
    <Link
      passHref
      href={getUserHref}
      as={asUrl}
      legacyBehavior
    >
      <a href="#!" target="_blank" rel="noreferrer">
        <ScreenNameStyled className={classNames( !hasCustomUserId && 'text-italic-asterisk' )}>{userIdentityName}</ScreenNameStyled>
      </a>
    </Link>
  </Wrapper>
})

const SessionNumber = memo(({ sessionRun, sessionId }) => {
  const { appId } = useSelector(state => state.urlReducer);
  const { dateSegment } = useSelector(state => state.appFilter);
  const asUrl = urlSegmentEncoder(`/app/${appId}/sessions/list/1/${sessionId}`, [...[dateSegment]])
  const getSessionHref = useMemo(() => ({
    pathname: '/integration',
    query: {
      parentType: 'sessionsList',
      appId,
      sessionpage: 1,
      sessionid: sessionId
    },
  }
  ), [appId, sessionId])

  return <Wrapper onClick={(e) => e.stopPropagation()}>
    <Link
      passHref
      href={getSessionHref}
      as={asUrl}
      legacyBehavior
    >
      <a href="#!" target="_blank" rel="noreferrer">
        <ScreenNameStyled>{sessionRun}</ScreenNameStyled>
      </a>
    </Link>
  </Wrapper>
})

const Location = memo(({ row }) => {
  const { city, country } = row.original;
  return (
    <LocationWrap className='title'>
      {city}
      <span className='subtitle'>{country}</span>
    </LocationWrap>
  )
})

const SessionReplay = memo(({ row }) => {
  const { id: visitIndex } = row;
  const { duration, entryTime, onRowClick, video, sessionLocked } = row.original;
  return (
    <ButtonAndTime>
      <>
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            if (sessionLocked) return;
            onRowClick(row.original, visitIndex);
          }}
        >
          {sessionLocked ? (
            <PlayLockIcon height={24} width={24} alt="play icon locked" />
          ) : video ? (
            <PauseIcon id="play-icon" />
          ) : (
            <NoVideoIcon id="play-icon" />
          )}
        </button>
        <span>
          {formatPlayerTime(entryTime)}/{formatPlayerTime(duration)}
        </span>
      </>
    </ButtonAndTime>
  );
})

const TimeRow = memo(({ value }) => (
  <>{convertGetTime({ durationInSecs: value })}</>
));

const CountRow = memo(({ value }) => <>{compactNotation(value, 2)}</>);
const CommonNameRow = memo(({ value }) => <span>{value}</span>);

const ColumnSelection = memo(({ cell, row }) => {
  const {
    column: { id, totalWidth },
  } = cell;
  const value = cell.getValue(id);
  const { original: originalRow } = row;

  switch (id) {
    case 'duration':
      return <SessionReplay row={row} />;
    case 'previousScreenName':
    case 'nextScreenName':
      return <ScreenNameRow id={id} width={totalWidth} row={row} />;
    case 'screenDuration':
      return <TimeRow value={value} />;
    case 'totalscreen': {
      const { screenNumber, totalscreen } = originalRow;
      const rowText = `${screenNumber} out of ${totalscreen}`;
      return <CommonNameRow value={rowText} />;
    }
    case 'city':
      return <Location row={row} />;
    case 'usersessionrun': {
      const { usersessionrun, sessionid } = originalRow;
      const sessionRun = `Session ${usersessionrun}`;
      return <SessionNumber sessionRun={sessionRun} sessionId={sessionid} />;
    }
    case 'sessionUploadedDateTime':
      return (
        <WrapperDate className='title'>
          {formatDisplayTime(value, 'MMM DD, yyyy')}
          <StyledSpan className='subtitle'>{getDate(value, 'EEE hh:mm  a')}</StyledSpan>
        </WrapperDate>
      );
    case 'uxcamuserid': {
      const { userProperty, uxcamuserid } = originalRow;
      const userIdConfig = getUserId({
        customUserId: userProperty?.kUXCam_UserIdentity,
        uxcamuserid,
      });
      return (
        <UserName
          userIdentityName={userIdConfig.availableUserId}  
          uxcamuserid={uxcamuserid}
          hasCustomUserId={userIdConfig.customUserId}
        />
      );
    }
    case 'rageTapCount':
    case 'screenGestureCount':
      return <CountRow value={value} />;
    default:
      return <CommonNameRow value={value} />;
  }
});
const getColumnWidth = (attribute) => {
  switch (attribute) {
    case 'duration':
    case 'screenDuration':
    case 'totalscreen':
      return 100;
    // case 'previousScreenName':
    // case 'nextScreenName':
    // case 'city':
    // case 'usersessionrun':
    // case 'sessionUploadedDateTime':
    // case 'uxcamuserid':
    //   return 150; // commented because by default it is 150
    default:
      return 150
  }
}

export default function useScreenVisitColumns(headers) {
  const columnHelper = createColumnHelper();

  const columns = useMemo(
    () =>
      headers
        .map((header) => {
          const {
            isVisible,
            attribute,
            title,
            titleInfo: tooltipInfo,
            isSortable,
          } = header;
          const width = getColumnWidth(attribute);
          return isVisible
            ? columnHelper.accessor(attribute, {
              header: <Tooltip title={tooltipInfo}><HeaderSpan>{title}</HeaderSpan></Tooltip>,
              cell: ({ cell, row }) => <ColumnSelection cell={cell} row={row} />,
              accessor: attribute,
              titleInfo: tooltipInfo,
              width,
              minWidth: width,
              enableSorting: isSortable,
            })
            : null;
        })
        .filter((el) => el),
    [headers]
  );

  return columns;
}
