import React, { useMemo, memo } from "react";
import styled from "styled-components";
import { useSelector } from "react-redux";
import { convertGetTime } from "Utils/helpers/commonUtils";
import GestureSvg from "../ScreenReplay/svgs/gesture.svg";
import NextScreenSvg from "../ScreenReplay/svgs/next-screen-name.svg";
import ClockSvg from "../ScreenReplay/svgs/clock-timing.svg"
import ScreenTootltipTitle from "./ScreenTooltipTitle";

const Title = styled.div`
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  &:first-child {
    font-weight: 500;
  }
  span:nth-child(6) {
    color: #FF0000
  }
`

const TitleSpan = styled.span`
  border-left: 1px solid #c0cad9;
  margin-left: 10px;
  padding-left: 10px;
  font-weight:400;
  display: inline-flex;
  align-items: center;
  font-size: 14px;

  svg {
    margin-right: 8px;
    fill: #FFFFFF;
  }
`

const EllipseText = styled.span`
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 280px;
`

const HeaderTitle = ({ screenInfo }) => {
  const {
    screenRenamedList: renamedScreens,
    urlReducer: { screenname },
  } = useSelector(({ screenRenamedList, urlReducer }) => ({
    screenRenamedList,
    urlReducer,
  }));
  const screenName = useMemo(
    () => renamedScreens[screenname] || screenname,
    [renamedScreens, screenname]
  );
  const { nextScreenName, screenDuration, screenNumber, screenGestureCount, totalscreen } = screenInfo || {};
  const nextScreenNameUpdated = useMemo(() => renamedScreens[nextScreenName] || nextScreenName , [renamedScreens, nextScreenName])
  return <Title>
    <EllipseText>{screenName}</EllipseText>
    <ScreenTootltipTitle title='Next screen the user visited after the current screen'>
      <TitleSpan><NextScreenSvg /><EllipseText>{nextScreenNameUpdated}</EllipseText></TitleSpan>
    </ScreenTootltipTitle>

    <ScreenTootltipTitle title='Number of the current screen in the sequence of all screens in this session'>
      <TitleSpan>Screen #{screenNumber} out of {totalscreen}</TitleSpan>
    </ScreenTootltipTitle>

    <ScreenTootltipTitle title='Number of gestures the user did during this screen visit'>
      <TitleSpan><GestureSvg />{screenGestureCount || 0}</TitleSpan>
    </ScreenTootltipTitle>

    <ScreenTootltipTitle title='Duration of this screen visit'>
      <TitleSpan><ClockSvg />{convertGetTime({ durationInSecs: screenDuration }) || ''} </TitleSpan>
    </ScreenTootltipTitle>

    {/* {rageTapCount > 0 &&
    <ScreenTootltipTitle title='Number of rage taps the user did during this screen visit'>
      <TitleSpan><RageSvg />{rageTapCount || ''} </TitleSpan>
    </ScreenTootltipTitle>} */}
  </Title>
}

export default memo(HeaderTitle);
