import { Modal } from "antd"
import React, { useCallback } from "react"
import styled, { createGlobalStyle } from "styled-components"
import { useRestrictionContext } from "components/IntegratePages/layout/context/restrictionContext"
import { useDispatch } from "react-redux"
import { trackPageViews } from 'redux/actions/trackingReport'

const GlobalStyles = createGlobalStyle`
	.session-locked-modal {
		z-index: 999999;
		display: flex;
		justify-content: center;
		align-items: center;
		.ant-modal {
			top: initial;
			transform-origin: center !important;
			width: 100% !important;
			max-width: 700px;
			margin: 50px;
		}
		.ant-modal-content {
			border-radius: 8px;
		}
	}
`

const Wrapper = styled.div`
	display: flex;
	position: relative;
	width: 100%;
`

const Right = styled.div`
	display: flex;
	flex-direction: column;
	justify-content: center;
	font-size: 14px;
	line-height: 24px;
	color: #161E35;
`

const Title = styled.h2`
	font-family: 'Roboto';
	font-style: normal;
	font-weight: 500;
	font-size: 18px;
	line-height: 24px;
	color: #161E35;
	margin-bottom: 16px;
`

const Buttons = styled.div`
	margin-top: 32px;
	display: flex;
	justify-content: flex-end;
`

const Button = styled.button`
	font-weight: 400;
	font-size: 14px;
	line-height: 24px;
	color: #FFFFFF;
	padding: 4px 21px;
	background-color: #5D97FF;
	border-radius: 6px;
	cursor: pointer;
	border: none;
	outline: none;
	width: fit-content;
	transition: all 0.2s ease-in-out;
	&:hover {
		background-color: #4A79CC;
	}
`

const ButtonSecondary = styled( Button )`
	margin-right: 16px;
	background-color: transparent;
	color: #5D97FF;
	&:hover {
		background-color: transparent;
		color: #4A79CC;
	}
`

const SessionLockedModal = () => {
	const { sessionLockedModal, setSessionLockedModal, selfServeFlag, setShowPricingModal } = useRestrictionContext()
	const dispatch = useDispatch()

	const handleClose = React.useCallback( () => {
		setSessionLockedModal( false )
	}, [ setSessionLockedModal ] )

	const handleShowPricing = useCallback(() => {
		setSessionLockedModal( false )
		setShowPricingModal(true)
		dispatch( trackPageViews( null, {
			eventName: selfServeFlag? 'wa_see_pricing_clicked' : 'wa_request_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'Video Access Modal'
			},
		} ) )
	}, [setShowPricingModal, setSessionLockedModal, selfServeFlag, dispatch])
	
	React.useEffect( () => {
		if ( sessionLockedModal ) {
			dispatch( trackPageViews( null, {
				eventName: 'wa_blocked_feature_pop_up_displayed',
				track_type: 'event',
				eventProperty: {
					source: 'Video Access Modal',
					self_chekout: selfServeFlag,
				},
			} ) )
		}
	}, [ sessionLockedModal, dispatch, selfServeFlag ] )

	return (
		<>
			<GlobalStyles />
			<Modal
				wrapClassName='session-locked-modal'
				visible={ sessionLockedModal }
				maskStyle={ { zIndex: '99998', background: 'rgba(22, 30, 53, 0.3)' } }
				getContainer={ () => document.body.querySelector( '.ant-layout-content' )}
				footer={ null }
				closable={ false }
				onCancel={ handleClose }
			>
				<Wrapper>
					<Right>
						<Title>
							Upgrade to watch this session
						</Title>
						Session videos recorded over 1 month ago are only accessible on the paid plans. 
						Upgrade to watch and get insights from all your sessions.
						<Buttons>
							<ButtonSecondary onClick={ handleClose }>
								Cancel
							</ButtonSecondary>
							<Button onClick={ handleShowPricing }>
								{ selfServeFlag ? "See pricing" : "Request pricing" }
							</Button>
						</Buttons>
					</Right>
				</Wrapper>
			</Modal>
		</>
	)
}

export default React.memo( SessionLockedModal )